# === cell 0 ===
# ============================================================================
# CONFIG - EDIT THIS CELL, then Run All
# ============================================================================
#
# Test set has 1001 pids (0..1000), ordered by random-walk length
# (pid 0 = easiest scramble, pid 1000 = hardest).
#
# Knobs:
#   START_PID, END_PID  - pid range to solve (half-open).
#   K_SYM               - FULL target sym-ensemble size, drawn from the
#                         720-element symmetry group. Practical: 1..16.
#                         Defines the deterministic canonical K_SYM-rotation
#                         list (seed=0). Both shards of a split run MUST set
#                         the same K_SYM, otherwise their position indices
#                         refer to different rotations.
#   SYM_POSITIONS       - which positions of the K_SYM ensemble THIS kernel
#                         actually runs (a range or list of ints in
#                         [0, K_SYM)). Lets one kernel run a slice and
#                         another run the rest; min-merge their CSVs.
#                         Memory does NOT scale with len(SYM_POSITIONS).
#   use_niss            - 0 = forward beam only.
#                         1 = also solve invert_state(S) and take the
#                         shorter path. Doubles wall PER (pid, sym_pos).
#                         Combines multiplicatively: total beam calls
#                         = N_PIDS * len(SYM_POSITIONS) * (2 if use_niss else 1).
#
# Split recipes (B=48M, ~78 min/beam-call; keep total beam calls <= 6):
#
#   K=8 across two kernels (recommended for hardest pids, no NISS):
#     Kernel A:  K_SYM=8, SYM_POSITIONS=range(0, 4), END_PID-START_PID=1, use_niss=0
#     Kernel B:  K_SYM=8, SYM_POSITIONS=range(4, 8), END_PID-START_PID=1, use_niss=0
#     1 pid x 4 calls x 1 niss = 4 beam calls per kernel ≈ 5.5 h.
#
#   K=8 split + NISS on the very hardest pid (most thorough recipe):
#     Kernel A:  K_SYM=8, SYM_POSITIONS=range(0, 2), END_PID-START_PID=1, use_niss=1
#     Kernel B:  K_SYM=8, SYM_POSITIONS=range(2, 4), END_PID-START_PID=1, use_niss=1
#     Kernel C:  K_SYM=8, SYM_POSITIONS=range(4, 6), END_PID-START_PID=1, use_niss=1
#     Kernel D:  K_SYM=8, SYM_POSITIONS=range(6, 8), END_PID-START_PID=1, use_niss=1
#     1 pid x 2 positions x 2 niss = 4 beam calls per kernel ≈ 5.5 h.
#
#   K=4 in one kernel (smaller ensemble, no split):
#     K_SYM=4, SYM_POSITIONS=range(0, 4)  (1 pid ≈ 5.5h; 2 pids over budget)
#
#   Smoke / identity only:
#     K_SYM=1, SYM_POSITIONS=range(0, 1)  (up to 6 pids in 9h)
# ============================================================================

START_PID = 990             # qshort-vs-Vonly A/B on a hard-tail pid
END_PID = 991
K_SYM = 1                    # single identity rotation (controlled A/B)
SYM_POSITIONS = range(0, 1)
use_niss = 0                  # 0 = forward only, 1 = also try inverse direction

# A/B: run the same pid/rotation at ALPHA_STUDENT=2 (qshort) and =24 (= keep ALL
# 24 children = V-only selection), everything else identical, to isolate whether
# the qshort prefilter costs path length. Prints [ALPHA_AB] lines; other cells
# may error after (harmless -- read the A/B output in run.log).
RUN_ALPHA_AB = False

# 96M-on-pid-990 DISK PROBE: confirm 96M+meta runs on a hard pid and print the
# real /kaggle/working disk size (memmap for a deep pid at 96M needs ~30GB, vs
# the 20GB *output* quota -- live disk may be larger). NUM_STEPS small (no solve).
B_GLOBAL = 96 * 1024 * 1024  # 96M needs meta-materialize (OOMs without it)
ALPHA_QSHORT = 2              # receive-side 2x oversampling for quality
ALPHA_STUDENT = 24           # =n_gen -> keep ALL children = V-only selection (no
                              # qshort prefilter). For THIS 96M/pid990 run: qshort
                              # a=2 costs ~10% on hard pids (v19 A/B: 84 vs 76), so
                              # use V-only to give 96M a real shot at beating 76.
                              # (Production default for coverage is 2.)
INTERNAL_BS = 16384
NUM_STEPS = 90              # full solve for deep pid 990 (~76+); memmap ~36GB -> /tmp (1.18TB free)

PARENT_CHUNK = 131072         # B_LOCAL / PARENT_CHUNK = 48 chunks per step
PACK_V_SCORE = True           # bf16 score packed into bucket; skip recv V re-run
PROGRESS_EVERY = 5            # print per-step timing every N steps

# --- Idea (2): solved-neighborhood (K1-ball) early-stop --------------------
# Detect when a beam state lands within NBHD_RADIUS moves of solved and append
# the BFS-optimal suffix, instead of waiting for the beam to reach solved
# exactly. Provably >= solve-rate and <= path length of the exact-only beam
# (each candidate is verified before it can be returned). One-time host BFS at
# kernel start; radius 5 ~ 1.38M states (~15-60s build, 12 MB device), radius 4
# ~ 97K (cheaper). Watch the per-step time on your first run -- the device adds
# a searchsorted over the ball each step; if it regresses, lower the radius.
USE_NEIGHBORHOOD = True
NBHD_RADIUS = 5

# --- Idea (1): approximate top-k (jax.lax.approx_min_k) --------------------
# Swap exact top_k for the TPU-optimized approx_min_k at the qshort prefilter
# and the final beam cut. recall_target < 1 trades a little selection accuracy
# for speed. OFF by default -- flip to True for an A/B once you've measured the
# baseline per-step wall (compare path lengths AND per-step time).
USE_APPROX_TOPK = False      # REJECTED (~0 speedup, +5 moves on pid 0); merge wasn't the bottleneck
APPROX_RECALL = 0.95

# --- Idea (4): compact-meta forward + deferred state materialization --------
# Ship 16-byte candidate metas in the forward all-to-all (vs 128-byte full-state
# packs) and re-materialize only the B survivors' states via a 2-hop round-trip.
# Selects the IDENTICAL beam (length-safe, verified on the CPU mesh); wins peak
# memory (~2x width headroom -> try B_GLOBAL=64M/96M, which OOM without it) and
# the memory-bound sort/gather/all-to-all. Speed is the open question (the
# materialize round-trip adds 2 all-to-alls + a survivor-state gather), so the
# first TPU run measures per-step vs the 46.4s baseline AND whether bigger B fits.
# ALPHA_REQ over-sizes the per-source request buckets; keep >=1.25 (survivor
# source-rank is uniform so overflow is ~0). Lower ALPHA_REQ = less resp padding
# = more width, but raises overflow risk.
USE_META_MATERIALIZE = True  # REQUIRED at 96M (streaming body OOMs); lean_merge n/a in meta path
ALPHA_REQ = 1.5

# Timing ablation (diagnostic): non-empty replaces ONE component with a cheap
# stand-in to measure its wall cost (WRONG beam -- read per-step device= only).
# "a2a" = skip the all-to-all; "argsort" = skip the recv dedup sort; "" = normal.
PROFILE_SKIP = ""            # "" = ablation off

# Lean merge (DEFAULT ON, validated): the scan carries compact provenance
# (parent_local + move + score) instead of the 1.5 GB pack; the 128 B send
# buckets are rebuilt ONCE post-scan (chunked apply-move + concat). Measured
# 46.4s -> 42.1s/step (~9% faster) at IDENTICAL paths (pid0 len 60, verify ok),
# and a ~10x smaller scan carry (bonus width headroom). Ablation showed the
# residual step cost is the per-chunk merge structure itself (irreducible
# without a bigger accumulate-once rewrite). Set False to use the legacy path.
LEAN_MERGE = True

